export function parseInitVaultConfigInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedInitVaultConfigInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === LEND_BORROW_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      vaultAdmin: getNextAccount(),
      vaultConfig: getNextAccount(),
      vaultMetadata: getNextAccount(),
      oracle: getNextAccount(),
      supplyToken: getNextOptionalAccount(),
      borrowToken: getNextOptionalAccount(),
      supplyDex: getNextOptionalAccount(),
      borrowDex: getNextOptionalAccount(),
      systemProgram: getNextAccount(),
    },
    data: getInitVaultConfigInstructionDataDecoder().decode(instruction.data),
  };
}
